ee:message.ee:set-payload:
%dw 2.0
output application/xml writeDeclaration=false
---
{
    "soapenv:Envelope" @(
        "xmlns:soapenv":"http://schemas.xmlsoap.org/soap/envelope/",
        "xmlns:int":"http://soap.sforce.com/schemas/class/IntegracionRemedy_ws"
        ): {
        "soapenv:Header": {
            "int:SessionHeader": {
                "int:sessionId": vars.token_response.access_token
            }
        },
        "soapenv:Body": {
            "int:WSActualizarObjeto": {
                "int:mensajeEntrada": {
                    "int:Id": payload.Id,
                    "int:lstObjetosHijosRelacionados": {
                        "int:ObjetosHijosRelacionados": payload.Notas map {
                            "int:Id": "",
                            "int:lstParametros": {
                                "int:Keys": {
                                    "int:Campo": "CommentTittle",
                                    "int:Valor": $.TituloNota
                                },
                                "int:Keys": {
                                    "int:Campo": "CommentBody",
                                    "int:Valor": $.DescripcionNota
                                }
                            },
                            "int:NombreRelacion": "CaseComments"
                        }
                    },
                    "int:NombreObjeto": "Case"
                }
            }
        }
    }
}
